#!/usr/bin/env python3
#
# Write ZeroS's overlay of the Updater's version strings for every language
# the Updater translates them in (bug B22). The overlay's values/ alone is not
# enough: a phone set to, say, English (India) uses the Updater's own
# values-en-rIN translation, which says "LineageOS 0.6.1". Each generated file
# is that translation with "LineageOS" replaced by "ZeroS", so each language
# keeps its own wording and date order.
#
# Run again after the Updater fork picks up new translations:
#   gen-updater-locale-overlays.py <android_packages_apps_Updater> <vendor/zeros>
#
# SPDX-License-Identifier: Apache-2.0
#
import pathlib
import re
import sys

NAMES = ("list_build_version", "list_build_version_date")
HEADER = """<?xml version="1.0" encoding="utf-8"?>
<!--
     Generated by vendor/zeros/build/tools/gen-updater-locale-overlays.py from
     the Updater's own translation (bug B22); do not edit by hand.
     SPDX-License-Identifier: Apache-2.0
-->
<resources xmlns:xliff="urn:oasis:names:tc:xliff:document:1.2">
"""

updater, vendor = map(pathlib.Path, sys.argv[1:3])
src = updater / "app/src/main/res"
dst = vendor / "overlay/packages/apps/Updater/app/src/main/res"
written = 0
for f in sorted(src.glob("values-*/strings.xml")):
    text = f.read_text(encoding="utf-8")
    lines = []
    for name in NAMES:
        m = re.search(r'^\s*<string name="%s"[^>]*>.*?</string>' % name, text, re.M | re.S)
        if m:
            line = re.sub(r"Lineage ?OS", "ZeroS", m.group(0).strip())
            if "Lineage" in re.sub(r'example="[^"]*"', "", line):
                sys.exit(f"{f}: {name} still names LineageOS: {line}")
            lines.append("    " + line)
    if not lines:
        continue
    out = dst / f.parent.name / "strings.xml"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(HEADER + "\n".join(lines) + "\n</resources>\n", encoding="utf-8")
    written += 1
print(f"{written} languages written to {dst}")
